<?php
declare(strict_types=1);
function api_json($data,int $status=200): void {http_response_code($status);header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store');echo json_encode($data,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);exit;}
function api_input(): array {$raw=file_get_contents('php://input');$j=json_decode($raw?:'{}',true);return is_array($j)?$j:$_POST;}
function api_bearer(): string {$h=(string)($_SERVER['HTTP_AUTHORIZATION']??'');if(preg_match('/^Bearer\\s+(.+)$/i',$h,$m))return trim($m[1]);return '';}
function api_issue_token(int $uid,string $device='Mobile App',string $scopes='profile,catalog,orders,pos'): array {$plain='shp_'.bin2hex(random_bytes(32));$hash=hash('sha256',$plain);$prefix=substr($plain,0,16);$days=max(1,min(365,setting_int('mobile_api_token_days',90)));db()->prepare("INSERT INTO mobile_api_tokens(user_id,token_hash,token_prefix,device_name,scopes,expires_at) VALUES(?,?,?,?,?,DATE_ADD(NOW(),INTERVAL {$days} DAY))")->execute([$uid,$hash,$prefix,substr($device,0,160),$scopes]);return ['token'=>$plain,'expires_in_days'=>$days,'scopes'=>explode(',',$scopes)];}
function api_user(): array {$token=api_bearer();if($token==='')api_json(['ok'=>false,'error'=>'Missing bearer token'],401);$hash=hash('sha256',$token);$q=db()->prepare("SELECT t.*,u.* FROM mobile_api_tokens t JOIN users u ON u.id=t.user_id WHERE t.token_hash=? AND t.revoked_at IS NULL AND (t.expires_at IS NULL OR t.expires_at>NOW()) AND u.status='active' LIMIT 1");$q->execute([$hash]);$u=$q->fetch();if(!$u)api_json(['ok'=>false,'error'=>'Invalid or expired token'],401);db()->prepare('UPDATE mobile_api_tokens SET last_used_at=NOW() WHERE token_hash=?')->execute([$hash]);return $u;}
function api_scope(array $u,string $scope): void {$scopes=array_filter(array_map('trim',explode(',',(string)($u['scopes']??''))));if(!in_array('*',$scopes,true)&&!in_array($scope,$scopes,true))api_json(['ok'=>false,'error'=>'Token scope denied'],403);}
function api_log_request(?int $uid,int $status=200): void {try{db()->prepare('INSERT INTO mobile_api_logs(user_id,endpoint,method,status_code,ip_address,duration_ms) VALUES(?,?,?,?,?,0)')->execute([$uid,substr((string)($_SERVER['REQUEST_URI']??''),0,190),substr((string)($_SERVER['REQUEST_METHOD']??'GET'),0,12),$status,security_client_ip()]);}catch(Throwable $e){}}
